            ALGORITHM_OPTIONS_SHAKE256 => Self::shake256_output_before(sum, sz, self.output_bits, not_file, self.tag, self.asterisk, self.length),
            _ => if self.tag { format!("{} (", self.algo_name.to_ascii_uppercase()) } else { format!("{} {}", sum, if self.asterisk { "*" } else { " " }) },
        }
    }

    fn dispatch_output_after(&self, sum: &str, not_file: bool) -> String {
        match self.algo_name {
