    fn dispatch_encode_raw(&self, sum_hex: &str) -> Vec<u8> {
        match self.algo_name {
            ALGORITHM_OPTIONS_SYSV => Self::sysv_encode_raw(sum_hex),
            ALGORITHM_OPTIONS_BSD => Self::bsd_encode_raw(sum_hex),
