            ALGORITHM_OPTIONS_SHA1 => Self::sha1_encode_raw(sum_hex),
            ALGORITHM_OPTIONS_SHA3 => Self::sha3_encode_raw(sum_hex),
            ALGORITHM_OPTIONS_SHA224 => Self::sha224_encode_raw(sum_hex),
            ALGORITHM_OPTIONS_SHA256 => Self::sha256_encode_raw(sum_hex),
            ALGORITHM_OPTIONS_SHA384 => Self::sha384_encode_raw(sum_hex),
