    fn dispatch_format_converted(&self, sum_hex: &str) -> String {
        match self.algo_name {
            ALGORITHM_OPTIONS_SYSV => Self::sysv_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_BSD => Self::bsd_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_CRC => Self::crc_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_MD5 => Self::md5_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_SHA1 => Self::sha1_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_SHA3 => Self::sha3_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_SHA224 => Self::sha224_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_SHA256 => Self::sha256_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_SHA384 => Self::sha384_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_SHA512 => Self::sha512_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_BLAKE2B => Self::blake2b_format_converted(sum_hex, &self.output_format),
            ALGORITHM_OPTIONS_BLAKE3 => Self::blake3_format_converted(sum_hex, &self.output_format),
