    fn dispatch_is_legacy_numeric(&self) -> bool {
        match self.algo_name {
            ALGORITHM_OPTIONS_SYSV => Self::sysv_is_legacy_numeric(),
            ALGORITHM_OPTIONS_BSD => Self::bsd_is_legacy_numeric(),
            ALGORITHM_OPTIONS_CRC => Self::crc_is_legacy_numeric(),
            ALGORITHM_OPTIONS_MD5 => Self::md5_is_legacy_numeric(),
