            ALGORITHM_OPTIONS_SHA3 => Self::sha3_is_legacy_numeric(),
            ALGORITHM_OPTIONS_SHA224 => Self::sha224_is_legacy_numeric(),
            ALGORITHM_OPTIONS_SHA256 => Self::sha256_is_legacy_numeric(),
            ALGORITHM_OPTIONS_SHA384 => Self::sha384_is_legacy_numeric(),
