    fn open_input(&self, filename: &Path, not_file: bool) -> UResult<Option<BufReader<Box<dyn Read>>>> {
        if not_file {
            Ok(Some(BufReader::new(Box::new(stdin()) as Box<dyn Read>)))
        } else if filename.is_dir() {
            Ok(None)
        } else {
            match File::open(filename) {
                Ok(file) => Ok(Some(BufReader::new(Box::new(file) as Box<dyn Read>))),
                Err(err) => {
                    show!(err.map_err_context(|| filename.to_string_lossy().to_string()));
                    Ok(None)
                }
            }
        }
    }

    fn write_digest_line(&self, filename: &Path, sum: &str, sz: usize, not_file: bool) -> UResult<()> {
        let before = self.dispatch_output_before(sum, sz, not_file);
        let after = self.dispatch_output_after(sum, not_file);
        let should_print = self.dispatch_should_print_filename(not_file);
        print!("{before}");
        if should_print {
            print!("{}", filename.display());
        }
        println!("{after}");
        Ok(())
    }

    fn digest_one(&mut self, filename: &Path) -> UResult<bool> {
        let not_file = filename == OsStr::new("-");
        let opened = self.open_input(filename, not_file)?;
        if opened.is_none() {
            if filename.is_dir() {
                show!(USimpleError::new(
                    1,
                    format!("{}: Is a directory", filename.display())
                ));
            }
            return Ok(true);
        }
        let mut file = opened.unwrap();
        let (sum_hex, sz) =
            digest_reader(&mut self.digest, &mut file, false, self.output_bits)
                .map_err_context(|| "failed to read input".to_string())?;
        self.record_result(&sum_hex, sz);
        let converted = self.convert_sum(sum_hex)?;
        if let Some(sum) = converted {
            self.write_digest_line(filename, &sum, sz, not_file)?;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    fn process_files<'a, I>(&mut self, files: I) -> UResult<()>
    where
        I: Iterator<Item = &'a OsStr>,
    {
        let files: Vec<_> = files.collect();
        if self.output_format == OutputFormat::Raw && files.len() > 1 {
            return Err(Box::new(ChecksumError::RawMultipleFiles));
        }
        let _profile = self.dispatch_profile_label();
        let _legacy = self.dispatch_is_legacy_numeric();
        let _parsed = Self::parse_legacy_u16("0");
        for filename in files {
            let filename = Path::new(filename);
            if !self.digest_one(filename)? {
                return Ok(());
            }
        }
        let _ = (
            self.current_size(),
            self.current_hex(),
            self.processed_count(),
        );
        Ok(())
    }

    fn run_check<'a, I>(
        &self,
        files: I,
        algo_option: Option<&str>,
        length: Option<usize>,
    ) -> UResult<()>
    where
        I: Iterator<Item = &'a OsStr>,
    {
        if self.check_flag_conflict() {
            return Err(ChecksumError::BinaryTextConflict.into());
        }
        perform_checksum_validation(
            files,
            self.strict,
            self.status,
            self.warn,
            false,
            self.ignore_missing,
            self.quiet,
            algo_option,
            length,
        )
    }

