    let after = self.dispatch_output_after(sum, not_file);
    let should_print = self.dispatch_should_print_filename(not_file);
    let stdout = stdout();
    let mut stdout = stdout.lock();
    stdout.write_all(before.as_bytes())?;
    if should_print {
        write_path(&mut stdout, filename)?;
    }
    writeln!(stdout, "{after}")?;
    Ok(())
}

